package com.driveraccounts.app;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.graphics.Typeface;import android.widget.*;import org.json.*;import java.text.*;import java.util.*;
public class MainActivity extends Activity {
 private static final int NAVY=Color.rgb(7,21,38), PANEL=Color.rgb(15,35,57), BLUE=Color.rgb(38,112,220), GREEN=Color.rgb(41,179,107), WHITE=Color.WHITE, MUTED=Color.rgb(175,193,210);
 private LinearLayout root; private EditText date; private HashMap<String,EditText> fields=new HashMap<>(); private JSONObject records;
 private final String[] labels={"Uber Credit","Uber Cash","Uber For Us","Yango Credit","Yango Cash","Yango For Us","Bolt Credit","Bolt Cash","Bolt For Us","OWN Trip","Card Collection","Company Trips","EV Charging","Car Expenses","Salik Toll","Uzair Collected"};
 @Override public void onCreate(Bundle b){super.onCreate(b);try{records=new JSONObject(getSharedPreferences("driveraccounts",0).getString("records","{}"));}catch(Exception e){records=new JSONObject();}showDashboard();}
 private void base(String title){root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(NAVY);root.setPadding(18,16,18,16);ScrollView sc=new ScrollView(this);sc.setFillViewport(true);sc.addView(root);setContentView(sc);root.addView(txt(title,24,WHITE,true));root.addView(txt("VERSION 8.9  •  OFFLINE",12,GREEN,true));}
 private TextView txt(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);if(bold)t.setTypeface(null,Typeface.BOLD);t.setPadding(0,8,0,8);return t;}
 private Button btn(String s,int color){Button b=new Button(this);b.setText(s);b.setTextColor(WHITE);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(color));return b;}
 private void showDashboard(){base("DriverAccounts");root.addView(txt("Daily Earnings  •  AED",18,WHITE,true));root.addView(txt(money(dailyTotal(today())),32,GREEN,true));Button entry=btn("＋  DAILY ENTRY",BLUE);root.addView(entry);entry.setOnClickListener(v->showEntry(today()));Button report=btn("DAILY REPORT / WHATSAPP SHARE",GREEN);root.addView(report);report.setOnClickListener(v->shareDaily(today()));Button monthly=btn("MONTHLY REPORT",BLUE);root.addView(monthly);monthly.setOnClickListener(v->showMonthly());Button history=btn("HISTORY / SELECT DATE",PANEL);root.addView(history);history.setOnClickListener(v->pickDate());root.addView(txt("TODAY'S SUMMARY",16,WHITE,true));for(String a:new String[]{"Uber","Yango","Bolt"})root.addView(txt(a+"   Credit: "+money(get(today(),a+" Credit"))+"   Cash: "+money(get(today(),a+" Cash"))+"   For Us: "+money(get(today(),a+" For Us")),14,MUTED,false));root.addView(txt("OWN Trip: "+money(get(today(),"OWN Trip"))+"   •   Salik: "+money(get(today(),"Salik Toll")),14,MUTED,false));root.addView(txt("Car Expenses: "+money(get(today(),"Car Expenses"))+"   •   EV: "+money(get(today(),"EV Charging")),14,MUTED,false));root.addView(txt("Uzair Collected: "+money(get(today(),"Uzair Collected")),14,MUTED,false));}
 private void showEntry(String d){base("Daily Entry");date=new EditText(this);date.setText(d);date.setTextColor(WHITE);date.setHint("YYYY-MM-DD");date.setSingleLine(true);root.addView(txt("Date",14,MUTED,false));root.addView(date);fields.clear();for(String l:labels){root.addView(txt(l,14,WHITE,true));EditText e=new EditText(this);e.setSingleLine(true);e.setInputType(8194);e.setTextColor(WHITE);e.setHint("0.00");e.setText(get(d,l)==0?"":String.valueOf(get(d,l)));fields.put(l,e);root.addView(e);}Button save=btn("SAVE DAILY RECORD",GREEN);root.addView(save);save.setOnClickListener(v->{String key=date.getText().toString().trim();if(key.length()<8){toast("Please enter a valid date");return;}JSONObject rec=new JSONObject();try{for(String l:labels)rec.put(l,val(fields.get(l).getText().toString()));records.put(key,rec);getSharedPreferences("driveraccounts",0).edit().putString("records",records.toString()).apply();toast("Saved successfully");showDashboard();}catch(Exception ex){toast("Could not save record");}});Button cancel=btn("BACK",PANEL);root.addView(cancel);cancel.setOnClickListener(v->showDashboard());}
 private void showMonthly(){base("Monthly Report");EditText month=new EditText(this);month.setText(today().substring(0,7));month.setTextColor(WHITE);month.setHint("YYYY-MM");root.addView(month);Button show=btn("SHOW REPORT",BLUE);root.addView(show);show.setOnClickListener(v->{String m=month.getText().toString();StringBuilder out=new StringBuilder("MONTHLY REPORT • "+m+"\n\n");double total=0;ArrayList<String> keys=new ArrayList<>();Iterator<String> it=records.keys();while(it.hasNext()){String k=it.next();if(k.startsWith(m)){keys.add(k);total+=dailyTotal(k);}}Collections.sort(keys);for(String k:keys)out.append(k).append("  AED ").append(money(dailyTotal(k))).append("\n");out.append("\nTOTAL EARNINGS: AED ").append(money(total)).append("\n\n");for(String l:labels){double sum=0;for(String k:keys)sum+=get(k,l);out.append(l).append(": AED ").append(money(sum)).append("\n");}root.addView(txt(out.toString(),14,WHITE,false));Button share=btn("SHARE MONTHLY REPORT",GREEN);root.addView(share);share.setOnClickListener(x->shareText(out.toString()));});Button back=btn("BACK",PANEL);root.addView(back);back.setOnClickListener(v->showDashboard());}
 private void pickDate(){Calendar c=Calendar.getInstance();new DatePickerDialog(this,(view,y,m,d)->showEntry(String.format(Locale.US,"%04d-%02d-%02d",y,m+1,d)),c.get(Calendar.YEAR),c.get(Calendar.MONTH),c.get(Calendar.DAY_OF_MONTH)).show();}
 private void shareDaily(String d){StringBuilder s=new StringBuilder("DRIVER ACCOUNTS • DAILY REPORT\nDate: "+d+"\n\n");for(String l:labels)s.append(l+": AED "+money(get(d,l))+"\n");s.append("\nDAILY EARNINGS: AED "+money(dailyTotal(d)));shareText(s.toString());}
 private void shareText(String s){Intent i=new Intent(Intent.ACTION_SEND);i.setType("text/plain");i.putExtra(Intent.EXTRA_TEXT,s);startActivity(Intent.createChooser(i,"Share report"));}
 private double dailyTotal(String d){return get(d,"Uber Credit")+get(d,"Yango Credit")+get(d,"Bolt Credit")+get(d,"Uber For Us")+get(d,"Yango For Us")+get(d,"Bolt For Us")+get(d,"OWN Trip");}
 private double get(String d,String field){JSONObject r=records.optJSONObject(d);return r==null?0:r.optDouble(field,0);}
 private double val(String s){try{return s.trim().isEmpty()?0:Double.parseDouble(s.trim());}catch(Exception e){return 0;}}
 private String money(double x){return String.format(Locale.US,"%.2f",x);}private String today(){return new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date());}private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}
}
